function legacySido(slug, kind){
  const i=slug.indexOf("-"); if(i<0) return null;
  for (const x of SIDO){
    if (slug.length>x.l.length+1 && slug.slice(0,x.l.length+1)===x.l+"-"){
      const L=LEGACY.get(x.l); if(!L) return null;
      return L[kind].has(slug.slice(x.l.length+1)) ? x : null;
    }
  }
  return null;
}

