const PROD = {
  "pos":               {name:"포스기",     img:"pos",               alt:"카페 계산대에서 주문을 받는 직원들"},
  "card-terminal":     {name:"카드단말기", img:"card-terminal",     alt:"진열대와 계산대가 있는 매장 내부"},
  "wireless-terminal": {name:"무선단말기", img:"wireless-terminal", alt:"테이블 좌석이 놓인 매장 내부"}
};
const PROD_KEYS = ["pos","card-terminal","wireless-terminal"];
function sidoUrl(p, sx){ return "/"+p+"/"+sx.s; }
function gunName(g){ return g==="세종특별자치시"?"세종시":g; }
function dongName(k){ const t=k.split("|"); return (t[0]==="세종특별자치시"?"":t[0]+" ")+t[1]; }
/* 층 정보가 있는 업소 가운데 2층 이상·지하 비율 */
function upperPct(x){ const f=x.fl, known=(f["1"]||0)+(f.up||0)+(f.B||0); return known? (f.up+f.B)*100/known : 0; }
function hiLo(a,b){ return a>=b ? "높고" : "낮고"; }
/* 순위 문구: 1위는 "가장", 꼴찌는 반대말로 */
function rk(r, hi, lo){ return r===1 ? "가장 "+hi : (r===SIDO.length ? "가장 "+lo : r+"번째로 "+hi); }
function hiLo2(a,b){ return a>=b ? "높습니다" : "낮습니다"; }

/* 시·도 페이지 공통 아래쪽: 같은 시·도 다른 제품 + 인접 시·도 같은 제품 + 관련 글 */
function sidoLinks(p, sx){
  const others=PROD_KEYS.filter(function(k){ return k!==p; }).map(function(k){
    return "<a href=\""+sidoUrl(k,sx)+"\">"+esc(sx.a+" "+PROD[k].name)+" 안내 →</a>"; }).join("");
  const near=sx.near.map(function(s){ const y=SIDO_BY_S.get(s); return "<a href=\""+sidoUrl(p,y)+"\">"+esc(y.a+" "+PROD[p].name)+"</a>"; }).join("");
  const posts=(POSTS_CACHE.rows||[]).slice(0,3).map(function(x){ return "<a href=\"/post/"+esc(x.slug)+"/\">"+esc(x.title)+"</a>"; }).join("");
  return "<div class=near><h3>"+esc(sx.a)+"의 다른 장비 안내</h3><div class=g>"+others+"</div></div>"+
    "<div class=near><h3>가까운 시·도의 "+esc(PROD[p].name)+" 안내</h3><div class=g>"+near+"<a class=more href=\"/"+p+"\">전국 "+esc(PROD[p].name)+" 안내 →</a></div></div>"+
    (posts?"<div class=near><h3>함께 읽을 글</h3><div class=g>"+posts+"</div></div>":"")+
    "<div class=near><h3>설치 전에 확인할 것</h3><div class=g><a href=\"/cost\">비용 구조 안내</a><a href=\"/install\">설치 절차와 준비 서류</a><a href=\"/faq\">자주 묻는 질문</a></div></div>";
}
function coverageFaq(sx){
  const x=STATS[sx.n];
  const q = x.gunN ? (sx.a+"의 군 지역(읍·면) 매장도 방문 설치가 되나요?") : (sx.a+" 어느 구·동에서든 방문 설치가 되나요?");
  const a = "방문 가능 지역과 일정: "+TODO+" 상담 때 매장 주소를 알려 주시면 가능한 날짜와 방법을 먼저 안내드립니다."+
    (NARR[sx.s].isl ? " "+esc(J(NARR[sx.s].isl,"은","는"))+" 배편·거리 때문에 일정을 따로 잡습니다." : "");
  return [q,a];
}
function gunSentence(sx){
  const x=STATS[sx.n];
  if(!x.gunN) return sx.a+"에는 군 지역이 없어 모든 업소가 시·구 지역에 있습니다.";
  const r=rankOf(sx,function(y){ return y.t? y.gun/y.t : 0; });
  return J(sx.a,"은","는")+" 업소의 "+pct(x.gun,x.t)+"%가 군 지역(군 "+x.gunN+"곳)에 있어, 17개 시·도 가운데 군 지역 비율이 "+rk(r,"높습니다.","낮습니다.");
}

