/* 업종 행을 전국 비중과 비교한 표 + 가장 두드러진 업종 */
function vsNation(rows, x){
  const out=rows.map(function(r){ const n=r[1](x), s=n*100/x.t, ns=r[1](NAT)*100/NAT.t; return {name:r[0], n:n, s:s, ns:ns, ratio:ns?s/ns:0, note:r[2]}; });
  const byRatio=out.slice().sort(function(a,b){ return b.ratio-a.ratio; });
  const byN=out.slice().sort(function(a,b){ return b.n-a.n; });
  return {rows:out, hi:byRatio[0], lo:byRatio[byRatio.length-1], top:byN};
}
function ratioText(r){ return r>=1 ? (r.toFixed(2)+"배") : (r.toFixed(2)+"배"); }
function vsTable(caption, label, v){
  return table(caption, [label,"업소 수","이 지역 비중","전국 비중","전국 대비"],
    v.rows.map(function(o){ return [esc(o.name), fmt(o.n), o.s.toFixed(2)+"%", o.ns.toFixed(2)+"%", ratioText(o.ratio)]; }), [1,2,3,4]);
}
function vsSentence(sx, v, what){
  const hi = v.hi.ratio>=1
    ? "전국보다 비중이 높은 "+what+" 가운데 "+esc(J(v.hi.name,"이","가"))+" 가장 두드러지고("+v.hi.s.toFixed(2)+"%, 전국의 "+v.hi.ratio.toFixed(2)+"배)"
    : "전국보다 비중이 높은 "+J(what,"이","가")+" 없고 전국과 가장 비슷한 것은 "+esc(v.hi.name)+"(전국의 "+v.hi.ratio.toFixed(2)+"배)이며";
  const lo = v.lo.ratio<1
    ? "전국보다 비중이 가장 낮은 것은 "+esc(v.lo.name)+"입니다("+v.lo.s.toFixed(2)+"%, 전국의 "+v.lo.ratio.toFixed(2)+"배). "
    : "전국과 차이가 가장 작은 것은 "+esc(v.lo.name)+"입니다(전국의 "+v.lo.ratio.toFixed(2)+"배). ";
  return "<p>"+esc(sx.a)+"에서는 "+hi+", "+lo+
    "업소 수로는 "+esc(v.top[0].name)+"("+fmt(v.top[0].n)+"곳), "+esc(v.top[1].name)+"("+fmt(v.top[1].n)+"곳), "+esc(v.top[2].name)+"("+fmt(v.top[2].n)+"곳) 순입니다.</p>";
}
/* 이 지역에서 먼저 볼 업종 두 개(가장 많은 업종 + 전국보다 두드러진 업종)의 구성 팁 */
function focusTips(v, head){
  const picks=[v.top[0]]; if(v.hi.name!==v.top[0].name) picks.push(v.hi); else picks.push(v.top[1]);
  return "<ul class=lst>"+picks.map(function(o){ return "<li><b>"+esc(o.name)+"</b> — "+esc(o.note)+"</li>"; }).join("")+"</ul>";
}
function shareTable(caption, label, list, total, cntLabel){
  let acc=0;
  const rows=list.map(function(g){ acc+=g[1]; return [esc(g[0].indexOf("|")>=0?dongName(g[0]):gunName(g[0])), fmt(g[1]), pct(g[1],total)+"%"]; });
  return {html:table(caption, [label,cntLabel||"업소 수","시·도 안 비중"], rows, [1,2]), sum:acc, n:rows.length};
}
function visitItems(sx){
  const it=["<b>방문 거리</b> — "+esc(gunSentence(sx))];
  if(NARR[sx.s].isl) it.push("<b>섬·원거리</b> — "+esc(J(NARR[sx.s].isl,"은","는"))+" 배편·거리 때문에 방문 일정을 따로 잡습니다.");
  return it;
}
function costOutro(){
  return "<p>장비 구성, 구매·렌탈·약정 방식, 월 이용료처럼 어느 지역에서나 같은 항목은 <a href=\"/cost\" style=\"color:var(--blue)\">비용 구조 안내</a>에 모아 두었습니다. 구체적인 금액은 매장 구성을 들은 뒤 견적으로 안내합니다.</p>";
}

