  const deliv=x.s["치킨"]+x.s["피자"]+x.s["버거"]+x.s["김밥/만두/분식"], ndeliv=NAT.s["치킨"]+NAT.s["피자"]+NAT.s["버거"]+NAT.s["김밥/만두/분식"];
