function productPage(p){
  const H=HUB[p], P=PROD[p], url=SITE+"/"+p, m=IMG[P.img];
  const cr=[["홈","/"],[P.name,"/"+p]];
  const inner=
    "<div class='r-eyebrow'>"+esc(P.name)+"</div>"+
    "<h1>"+esc(H.h1)+"</h1>"+lastMod()+
    "<figure style=\"margin:18px 0 6px\">"+imgTag(P.img, P.alt, {eager:true, sizes:"(max-width:768px) 100vw, 720px"})+
      "<figcaption style=\"font-size:12px;color:var(--muted);margin-top:6px\">참고용 사진(스톡) · 실제 설치 사진 "+TODO+"</figcaption></figure>"+
    H.lead()+H.body()+
    "<h2>비용은 어떻게 정해지나요</h2><p>장비 구성, 구매·렌탈·약정 방식, 월 이용료, 방문 거리에 따라 달라집니다. 가격표 대신 매장 구성을 들은 뒤 견적으로 안내합니다. 항목별 설명은 <a href=\"/cost\" style=\"color:var(--blue)\">비용 구조 안내</a>를 보세요.</p>"+
    "<h2>자주 묻는 질문</h2>"+faqBlock(H.faq.map(function(f){ return [f[0], esc(f[1])]; }))+
    srcNote()+
    ctaBox(P.name+" 상담", "매장 위치와 업종, 지금 쓰는 장비를 알려 주시면 맞는 구성을 정리해 드립니다.")+
    "<div class=near><h3>다른 장비 안내</h3><div class=g>"+PROD_KEYS.filter(function(k){return k!==p;}).map(function(k){ return "<a href=\"/"+k+"\">"+PROD[k].name+" 안내 →</a>"; }).join("")+"</div></div>";
  const jsonld=[orgLd(),
    {"@context":"https://schema.org","@type":"Service","name":P.name+" 설치 안내","serviceType":P.name+" 설치","url":url,"provider":orgRef(),"areaServed":{"@type":"Country","name":"대한민국"},"description":H.desc},
    crumbLd(cr), faqLd(H.faq)];
  return shell({title:H.title, desc:H.desc, url:url, jsonld:jsonld, nav:"/"+p, image:SITE+imgUrl(P.img,1200),
    preload:{href:imgUrl(P.img,m.s[m.s.length-1]), srcset:m.s.map(function(w){ return imgUrl(P.img,w)+" "+w+"w"; }).join(", "), sizes:"(max-width:768px) 100vw, 720px"}}, pageFrame({crumbs:cr}, inner));
}


