function staticPage(o){
  const url=SITE+o.path, cr=[["홈","/"],[o.crumb||o.h1,o.path]];
  const inner="<div class='r-eyebrow'>"+esc(o.eyebrow||BRAND)+"</div><h1>"+esc(o.h1)+"</h1>"+lastMod()+o.html+
    (o.cta===false?"":ctaBox(o.ctaT||"상담 문의", o.ctaB||"매장 위치와 업종, 지금 쓰는 장비를 알려 주시면 맞는 구성을 정리해 드립니다."));
  const jsonld=[orgLd(), {"@context":"https://schema.org","@type":o.type||"WebPage","name":o.h1,"url":url,"inLanguage":"ko-KR","dateModified":CONTENT_DATE,"publisher":orgRef()}, crumbLd(cr)];
  if(o.faq) jsonld.push(faqLd(o.faq));
  return shell({title:o.title, desc:o.desc, url:url, jsonld:jsonld, nav:o.path}, pageFrame({crumbs:cr}, inner));
}
function li(arr){ return "<ul class=lst>"+arr.map(function(x){ return "<li>"+x+"</li>"; }).join("")+"</ul>"; }

