function tgDescribe(path){
  const seg=String(path||'').split('?')[0].split('/').filter(Boolean);
  if(!seg.length) return '메인';
  const p0=seg[0];
  if(PROD[p0]){ const sx=seg[1]?SIDO_BY_S.get(seg[1]):null; return sx?(sx.n+' '+PROD[p0].name):(PROD[p0].name+' 안내'); }
  const FIXED_LABEL={about:'회사 소개',cost:'비용 안내',install:'설치 절차',faq:'자주 묻는 질문',contact:'상담 문의',privacy:'개인정보처리방침',terms:'이용약관',post:'포스기 정보'};
  if(FIXED_LABEL[p0]) return FIXED_LABEL[p0];
  if((p0==='r'||p0==='card'||p0==='sido'||p0==='sigungu')&&seg[1]) return '옛 지역 페이지';
  return '일반 페이지';
}
function tgRef(ref){
  if(!ref) return '직접 방문 또는 알 수 없음';
  try{
    const h=new URL(ref).hostname.replace(/^www\./,'');
    if(h===TG_DOMAIN||h.endsWith('.'+TG_DOMAIN)) return '사이트 내부 이동';
    if(h.includes('naver')) return '네이버';
    if(h.includes('google')) return '구글';
    if(h.includes('daum')) return '다음';
    if(h.includes('bing')) return 'Bing';
    if(h.includes('kakao')) return '카카오';
    if(h.includes('instagram')) return '인스타그램';
    if(h.includes('facebook')) return '페이스북';
    if(h.includes('youtube')) return '유튜브';
    if(h.includes('tiktok')) return '틱톡';
    if(h.includes('zum')) return '줌';
    return h;
  }catch(e){ return '알 수 없음'; }
}
function tgTime(){
  const d=new Date(Date.now()+9*3600000);
  const z=n=>String(n).padStart(2,'0');
  return d.getUTCFullYear()+'-'+z(d.getUTCMonth()+1)+'-'+z(d.getUTCDate())+' '+z(d.getUTCHours())+':'+z(d.getUTCMinutes());
}
const TG_BOT_RE = /bot|crawl|spider|slurp|facebookexternalhit|curl|wget|python|axios|headless|lighthouse|pagespeed|semrush|ahrefs|bytespider|applebot|monitor|uptime|scan/i;

/* ── 서버 측 연타 방어 ──────────────────────────────────────────
   클라이언트 디바운스는 새 탭·시크릿창·브라우저 재시작으로 초기화된다.
   같은 site+type+page+ip 가 TK_DUP_MS 안에 이미 기록돼 있으면 중복으로 보고 버린다.
   조회가 실패하면 false 를 돌려 추적 자체는 절대 막지 않는다. */
const TK_DUP_MS = 2 * 60 * 1000;   /* 실측: 연타 간격 중앙 5초·최대 57초. 10분은 공유 IP(CGNAT) 오탐만 키웠다 */
async function tkDup(env, site, type, page, ip) {
  if (!env || !env.DB || !ip || type === 'view') return false;
  try {
    const since = new Date(Date.now() - TK_DUP_MS).toISOString();
    const row = await env.DB.prepare(
      'SELECT 1 FROM events WHERE site=? AND type=? AND page=? AND ip=? AND ts>? LIMIT 1'
    ).bind(site, type, page, ip, since).first();
    if (row) console.log('tkDup 차단 site=' + site + ' type=' + type + ' ip=' + ip + ' page=' + page);
    return !!row;
  } catch (e) { return false; }
}

async function tgNotify(env, type,page,ref,ua,btn,qs){
  const TG_TOKEN = env && env.TG_TOKEN;
  const TG_CHAT = env && env.TG_CHAT;
  if (!TG_TOKEN || !TG_CHAT) return;
  const label=TG_LABEL[type];
  if(!label) return;
  const L=[];
  L.push((type==='tel'?'📞 ':'📝 ')+label);
  L.push('');
  L.push('사이트: '+TG_SITE+' ('+TG_DOMAIN+')');
  L.push('주소: '+TG_ORIGIN+page);
  L.push('페이지: ' + tgDescribe(page));
  /* 라벨이 '상담' 인데 실제로는 sms:/tel: 링크인 버튼이 있어 눌린 버튼 이름을 그대로 싣는다 */
  if (btn) L.push('버튼: ' + btn);
  /* ref 에서 뽑은 진짜 검색어 — 없으면 줄 자체를 넣지 않는다 */
  const __ai = tkAi(ref, qs);
  const __kw = __ai ? '' : tkKeyword(ref);
  if (__kw) L.push('검색어: ' + __kw);
  L.push('유입: ' + (__ai ? 'AI · ' + __ai : tgRef(ref)));
  L.push('기기: '+(/Mobile|Android|iPhone|iPad/i.test(ua||'')?'모바일':'PC'));
  L.push('시각: '+tgTime()+' (KST)');
  {
    /* 텔레그램 API 가 429/5xx 를 주는 경우가 있어 최대 3회 재시도한다.
       실패는 조용히 삼키지 않고 로그로 남겨 wrangler tail 에서 확인할 수 있게 한다. */
    const __body = JSON.stringify({chat_id:TG_CHAT,text:L.join('\n'),disable_web_page_preview:true});
    for (let __i = 0; __i < 3; __i++) {
      let __st = 0;
      try {
        const __r = await fetch('https://api.telegram.org/bot' + TG_TOKEN + '/sendMessage', {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, body: __body
        });
        if (__r && __r.ok) return;
        __st = __r ? __r.status : 0;
      } catch (e) { __st = -1; }
      console.log('tgNotify 실패 type=' + type + ' status=' + __st + ' try=' + (__i + 1));
      if (__i < 2) await new Promise(function (s) { setTimeout(s, 400 * (__i + 1)); });
    }
  }
}
