/* ── 스크래퍼 차단 ──────────────────────────────────────────
   라우팅·렌더링 전에 끊는다. 계정에 WAF 쓰기 권한이 없어 워커에서 처리한다.
   185.218.86.11 = TC DATACENTER LIMITED (AMS 경유). 1시간에 2만 요청,
   위장 UA Firefox/47.0, PUT 남발로 504 를 유발했다.
   허용 메서드는 GET/POST/HEAD/OPTIONS 뿐이다. */
const BLOCK_IPS = new Set(["185.218.86.11"]);
const BLOCK_UA_RE = /Firefox\/47\.0\b/i;
const ALLOWED_METHODS = new Set(["GET", "POST", "HEAD", "OPTIONS"]);
function blockScraper(request){
  const nostore = { "cache-control": "no-store" };
  if(!ALLOWED_METHODS.has(request.method))
    return new Response("Method Not Allowed", { status: 405, headers: Object.assign({ "allow": "GET, POST, HEAD, OPTIONS" }, nostore) });
  if(BLOCK_IPS.has(request.headers.get("cf-connecting-ip") || ""))
    return new Response("Forbidden", { status: 403, headers: nostore });
  if(BLOCK_UA_RE.test(request.headers.get("user-agent") || ""))
    return new Response("Forbidden", { status: 403, headers: nostore });
  return null;
}

/* ═══════════════ 크롤러 방문 · IndexNow 제출 기록 (semogwa 2026-09-11 이식) ═══════════════
   events 는 브라우저 JS 비컨으로만 채워져서 크롤러는 한 줄도 안 남는다.
   "네이버 Yeti 가 실제로 오는가"를 보려면 서버가 직접 crawl_hits 에 적어야 한다. */
const CRAWLER_BOTS = [
  [/yeti/i,                                  "Yeti"],        /* 네이버 */
  [/daumoa|cs\.daum\.net|compatible;\s*daum\//i, "Daum"],
  [/google-inspectiontool/i,                 "GoogleInspect"],
  [/googleother/i,                           "GoogleOther"],
  [/googlebot|mediapartners-google/i,        "Googlebot"],
  [/bingbot|adidxbot/i,                      "bingbot"],
  [/yandex/i,                                "YandexBot"],
  [/petalbot/i,                              "PetalBot"],
  [/bytespider/i,                            "Bytespider"],
  [/applebot/i,                              "Applebot"],
  [/gptbot|oai-searchbot|chatgpt-user/i,     "OpenAI"],
  [/claudebot|claude-web|anthropic/i,        "ClaudeBot"],
  [/perplexity/i,                            "PerplexityBot"],
  [/facebookexternalhit|meta-external/i,     "Facebook"],
];
function crawlerName(ua){
  if(!ua) return "";
  for(const [re,name] of CRAWLER_BOTS) if(re.test(ua)) return name;
  return BOT_UA_RE.test(ua) ? "기타봇" : "";
}
/* 응답을 돌려준 뒤 waitUntil 로 적는다. D1 이 느리거나 실패해도 응답에는 영향이 없다. */
function logCrawl(env, ctx, request, status){
  try{
    if(!env||!env.DB) return;
    const ua=request.headers.get("user-agent")||"";
    const bot=crawlerName(ua);
    if(!bot) return;
    const u=new URL(request.url);
    const q=(u.pathname+u.search).replace(/([?&]key=)[^&]*/gi,"$1***");   /* /indexnow/*?key= 마스킹 */
    const cf=request.cf||{};
    const pr=env.DB.prepare('INSERT INTO crawl_hits (site,bot,ua,host,path,status,ts,ip,asn,country) VALUES (?,?,?,?,?,?,?,?,?,?)')
      .bind('365posmall', bot, ua.slice(0,250), u.host.slice(0,80), q.slice(0,300),
            status|0, new Date().toISOString(), request.headers.get("cf-connecting-ip")||"",
            cf.asn|0, cf.country||"")
      .run();
    const done=Promise.resolve(pr).catch(()=>{});
    if(ctx&&ctx.waitUntil) ctx.waitUntil(done);
  }catch(e){}
}
/* IndexNow 제출 결과 — 응답 코드를 버리지 않고 배치마다 한 줄씩 남긴다. */
function logIndexnow(env, ctx, row){
  try{
    if(!env||!env.DB) return;
    const pr=env.DB.prepare('INSERT INTO indexnow_log (site,ts,source,start_idx,count,status,endpoint,attempt,note) VALUES (?,?,?,?,?,?,?,?,?)')
      .bind('365posmall', new Date().toISOString(), row.source||"", row.start|0, row.count|0,
            row.status|0, (row.ep||"").slice(0,80), row.attempt|0, (row.note||"").slice(0,200))
      .run();
    const done=Promise.resolve(pr).catch(()=>{});
    if(ctx&&ctx.waitUntil) ctx.waitUntil(done); else return done;
  }catch(e){}
}


function notFound(){
  return shell({title:"페이지를 찾을 수 없습니다 — "+BRAND, desc:"요청하신 페이지가 없습니다.", url:SITE+"/", noindex:true},
   "<div class=col><section class=hero><span class=eyebrow><i></i>404</span><h1 class=serif style=\"font-size:clamp(30px,6vw,56px);margin-top:16px\">페이지를 찾을 수 없습니다.</h1>"+
   "<p class=sub>주소가 바뀌었거나 없는 페이지입니다. <a href=\"/\" style=\"color:var(--blue);text-decoration:underline\">홈</a>에서 장비와 시·도를 골라 보세요.</p></section>"+
   "<div class=near><div class=g>"+PROD_KEYS.map(function(k){ return "<a href=\"/"+k+"\">"+PROD[k].name+" 안내</a>"; }).join("")+"<a href=\"/faq\">자주 묻는 질문</a></div></div></div>");
}
function resp(html,type,extra){
  return new Response(html,{headers:Object.assign({"content-type":type,"cache-control":"public, max-age=600"},extra||{})});
}
function moved(path){ return new Response(null,{status:301,headers:{"location":SITE+path,"cache-control":"public, max-age=86400"}}); }

/* 새 페이지 라우팅 — 있으면 HTML, 없으면 null */
function renderPage(path){
  if(path==="/") return homePage();
  if(PAGES[path]) return PAGES[path]();
  const seg=path.split("/");               // ["", 제품, 시도]
  if(seg.length===2 && PROD[seg[1]]) return productPage(seg[1]);
  if(seg.length===3 && PROD[seg[1]]){ const sx=SIDO_BY_S.get(seg[2]); if(sx) return sidoProductPage(seg[1], sx); }
  return null;
}
/* 옛 주소 → 새 주소. 모르는 슬러그면 null(404) */
function legacyTarget(path){
  const seg=path.split("/");
  if(seg.length!==3 || !seg[2]) return null;
  const k=seg[1], slug=seg[2];
  if(k==="r")      { const sx=legacySido(slug,"r"); return sx ? sidoUrl("pos",sx) : null; }
  if(k==="card")   { const sx=legacySido(slug,"r"); return sx ? sidoUrl("card-terminal",sx) : null; }
  if(k==="sigungu"){ const sx=legacySido(slug,"g"); return sx ? sidoUrl("pos",sx) : null; }
  if(k==="sido")   { const sx=SIDO_BY_L.get(slug); return sx ? sidoUrl("pos",sx) : null; }
  return null;
}
const HOME_MOVED = new Set(["/list","/sitemap.html","/find"]);

const __APP = {
  async fetch(request, env, ctx){
    const __blk = blockScraper(request); if(__blk) return __blk;
    const url=new URL(request.url);
    let path=url.pathname;
    try{ path=decodeURIComponent(path); }catch(e){}
    if(path==="/api/track"&&request.method==="POST"){try{const b=await request.json();
    /* 같은 방문자가 같은 버튼을 반복해 눌러도 1건만 기록·발송한다 */
    if (await tkDup(env, '365posmall', b.type, (b.page || '').slice(0, 300), request.headers.get('CF-Connecting-IP') || '')) {
      return new Response(JSON.stringify({ ok: true, dup: 1 }), { headers: { 'content-type': 'application/json', 'access-control-allow-origin': '*' } });
    }
const ua=request.headers.get("User-Agent")||"";if(!TG_BOT_RE.test(ua)&&TG_LABEL[b.type]){const tgp=tgNotify(env, b.type,(b.page||"/").slice(0,300),b.ref||"",ua, String(b.b || "").slice(0, 40), b.q||"");if(ctx&&ctx.waitUntil)ctx.waitUntil(tgp);else await tgp;}const ip=request.headers.get("CF-Connecting-IP")||"";const ts=new Date().toISOString();if(env&&env.DB&&!(b.type==="view"&&BOT_UA_RE.test(request.headers.get("User-Agent")||"")||(b.type==="view"&&skipViewCf(request, request.headers.get("CF-Connecting-IP")||"")))&&(b.type==="tel"||b.type==="sms"||b.type==="contact"||b.type==="view")){await env.DB.prepare('INSERT INTO events (site,type,page,ref,ip,ts,ua,device,source,keyword) VALUES (?,?,?,?,?,?,?,?,?,?)')
            .bind('365posmall', b.type, (b.page||'').slice(0,300), (b.ref||'').slice(0,120), ip, ts, ...tkMeta(request.headers.get('User-Agent')||'', b.ref||'', '365posmall.com', b.q||"")).run();}}catch(e){}return new Response(JSON.stringify({ok:true}),{headers:{"Content-Type":"application/json","Access-Control-Allow-Origin":"*"}});}
    if(path==="/api/track"&&request.method==="OPTIONS")return new Response(null,{headers:{"Access-Control-Allow-Origin":"*","Access-Control-Allow-Methods":"POST,OPTIONS","Access-Control-Allow-Headers":"Content-Type"}});
    if(path==="/robots.txt") return new Response(ROBOTS,{headers:{"content-type":"text/plain; charset=UTF-8","cache-control":"no-cache, no-store, max-age=0"}});
    if(path==="/llms.txt") return resp(llmsTxt(),"text/plain; charset=UTF-8");
    if(GOOGLE_VERIFY_FILE && path==="/"+GOOGLE_VERIFY_FILE) return resp("google-site-verification: "+GOOGLE_VERIFY_FILE,"text/plain; charset=UTF-8");
    if(BING_VERIFY && path==="/BingSiteAuth.xml") return resp('<?xml version="1.0"?><users><user>'+BING_VERIFY+'</user></users>',"application/xml; charset=UTF-8");
    if(INDEXNOW_KEY && path==="/"+INDEXNOW_KEY+".txt") return resp(INDEXNOW_KEY,"text/plain; charset=UTF-8");
    if(path==="/indexnow/today"||path==="/indexnow/all"){
      if(url.searchParams.get("key")!==INDEXNOW_KEY) return new Response("forbidden",{status:403});
      await loadPosts(env);
      const urls=path.endsWith("/all")?allUrls():postFreshUrls();
      const res=await submitIndexNow(urls,env,null,"manual");
      return new Response(JSON.stringify({requested:urls.length,sent:res.sent,batches:res.batches,naver:res.naver}),{headers:{"content-type":"application/json; charset=UTF-8"}});
    }
    if(path==="/og.svg") return resp(OG_SVG,"image/svg+xml");
    if(path==="/favicon.svg") return resp(FAVICON_SVG,"image/svg+xml");
    if(path==="/favicon.ico") return new Response(b64bytes(FAVICON_ICO_B64),{headers:{"content-type":"image/x-icon","cache-control":"public, max-age=86400"}});
    if(path==="/favicon-48.png") return new Response(b64bytes(FAVICON_PNG48_B64),{headers:{"content-type":"image/png","cache-control":"public, max-age=86400"}});
    if(path==="/favicon-32.png") return new Response(b64bytes(FAVICON_PNG32_B64),{headers:{"content-type":"image/png","cache-control":"public, max-age=86400"}});
    if(path==="/apple-touch-icon.png"||path==="/apple-touch-icon-precomposed.png") return new Response(b64bytes(APPLE_PNG_B64),{headers:{"content-type":"image/png","cache-control":"public, max-age=86400"}});

    /* 옛 주소 1.3만 — 한 번에 새 페이지(200)로 */
    if(HOME_MOVED.has(path)) return moved("/");
    const lg=legacyTarget(path); if(lg) return moved(lg);
    if(path==="/sitemap-main.xml"||path==="/sitemap-r.xml"||path==="/sitemap-card.xml") return moved("/sitemap.xml");

    await loadPosts(env);
    if(path==="/sitemap.xml") return resp(sitemapAll(),"application/xml; charset=UTF-8",{"cache-control":"public, max-age=3600"});
    if(path==="/rss.xml"||path==="/feed.xml"||path==="/rss"||path==="/feed") return resp(rssFeed(),"application/rss+xml; charset=UTF-8");
    if(path==="/atom.xml"||path==="/atom") return resp(atomFeed(),"application/atom+xml; charset=UTF-8");

    /* 정보성 글 */
    if(path==="/post") return moved("/post/");
    if(path==="/post/"){ return resp(pagePostList(POSTS_CACHE.rows||[]),"text/html; charset=UTF-8"); }
    if(path.startsWith("/post/")){
      const __s=path.slice(6).replace(/\/+$/,"");
      if(__s && __s.indexOf("/")<0){ const __p=await getPost(env,__s); if(__p) return resp(pagePost(__p),"text/html; charset=UTF-8"); }
      return new Response(notFound(),{status:404,headers:{"content-type":"text/html; charset=UTF-8"}});
    }

    const html=renderPage(path);
    if(html) return resp(html,"text/html; charset=UTF-8");
    /* 끝 슬래시만 다른 주소는 정식 주소로 */
    if(path.length>1 && path.endsWith("/")){
      const bare=path.replace(/\/+$/,"");
      if(renderPage(bare)) return moved(bare);
      const lg2=legacyTarget(bare); if(lg2) return moved(lg2);
      if(HOME_MOVED.has(bare)) return moved("/");
    }
    return new Response(notFound(),{status:404,headers:{"content-type":"text/html; charset=UTF-8"}});
  },
  async scheduled(event,env,ctx){
    try{ POSTS_CACHE.at=0; await loadPosts(env); }catch(e){}
    /* 매일 전 페이지 제출은 폐기했다 — 최근 7일 안에 발행된 글이 있을 때만 제출한다 */
    const fresh=postFreshUrls();
    if(fresh.length) ctx.waitUntil(submitIndexNow(fresh,env,null,"cron"));
  }
};

/* 기존 라우팅(__APP.fetch)을 감싸 응답 뒤에 크롤러 방문을 기록한다 */
export default {
  async fetch(request, env, ctx){
    const res = await __APP.fetch(request, env, ctx);
    logCrawl(env, ctx, request, res.status);      /* 실패해도 응답에는 영향 없음 */
    return res;
  },
  async scheduled(event, env, ctx){ return __APP.scheduled(event, env, ctx); }
};
